import { Question } from "./types";

function makeListeningQ(
  id: string, level: "n5" | "n4", type: string, audioIdx: number,
  audioText: string, question: string, options: string[], correct: number,
  romaji: string, translation: string
): Question {
  return {
    id, level, section: "listening", type,
    prompt: question,
    promptJp: audioText,
    options, correct,
    explanation: `${audioText}\n${romaji}\n${translation}`,
    audio: `/audio/${level}/q${audioIdx}.mp3`,
    audioSlow: `/audio/${level}/q${audioIdx}_slow.mp3`,
  };
}

